#!/usr/bin/env node
// Scaling investigation benchmark (comparison/results.md "Scaling to
// 10k-30k points"). Loads scripts/scale_data/scale_n{N}_d32.f32 (raw
// float32, row-major, generated by scripts/gen_scale_test_data.py) and
// times both wasm builds' end-to-end evoc_fit_predict AND standalone
// per-stage exports (knn_graph, boruvka_mst, node_embedding,
// cluster_tree_labels) at each size, reporting wall-clock time and
// memory.buffer.byteLength after each call.
//
// Usage: node scripts/wasm_scale_benchmark.mjs [n1,n2,...]
// Default sizes: 2000,10000,30000. A per-call timeout is enforced via
// worker isolation is NOT implemented here (wasm calls are synchronous JS
// and can't be preempted); instead each size is run in a fresh child
// process with a hard wall-clock timeout so a hang can be reported as
// "did not complete" rather than blocking the whole benchmark run.

import { readFileSync, existsSync } from "node:fs";
import path from "node:path";
import { ROOT } from "./wasm_fixture_lib.mjs";

const RUST_WASM = path.join(ROOT, "rust", "target", "wasm32-unknown-unknown", "release", "evoc_core.wasm");
const ZIG_WASM = path.join(ROOT, "zig", "zig-out", "bin", "evoc_core.wasm");
const DATA_DIR = path.join(ROOT, "scripts", "scale_data");
const N_FEATURES = 32;

function loadData(n) {
  const p = path.join(DATA_DIR, `scale_n${n}_d${N_FEATURES}.f32`);
  if (!existsSync(p)) throw new Error(`missing ${p}; run: python3 scripts/gen_scale_test_data.py`);
  const buf = readFileSync(p);
  return new Float32Array(buf.buffer, buf.byteOffset, buf.byteLength / 4);
}

function fmtMs(ms) {
  return ms >= 1000 ? (ms / 1000).toFixed(2) + " s" : ms.toFixed(1) + " ms";
}
function fmtBytes(b) {
  return (b / (1024 * 1024)).toFixed(1) + " MiB";
}

async function time(label, fn) {
  const t0 = performance.now();
  const result = fn();
  const t1 = performance.now();
  console.log(`    ${label.padEnd(28)} ${fmtMs(t1 - t0).padStart(10)}`);
  return result;
}

// --- Rust adapter ---
class RustCore {
  constructor(instance) {
    this.exports = instance.exports;
    this.memory = this.exports.memory;
  }
  alloc(len) {
    const ptr = this.exports.wasm_alloc(len);
    if (ptr === 0) throw new Error(`wasm_alloc(${len}) failed`);
    return ptr;
  }
  dealloc(ptr, len) {
    this.exports.wasm_dealloc(ptr, len);
  }
  writeF32(arr) {
    const ptr = this.alloc(arr.length * 4);
    new Float32Array(this.memory.buffer, ptr, arr.length).set(arr);
    return { ptr, len: arr.length * 4 };
  }
  free(...bufs) {
    for (const b of bufs) this.dealloc(b.ptr, b.len);
  }
  memBytes() {
    return this.memory.buffer.byteLength;
  }
}

async function loadRust() {
  const bytes = readFileSync(RUST_WASM);
  const { instance } = await WebAssembly.instantiate(bytes, {});
  return new RustCore(instance);
}

// --- Zig adapter ---
class ZigCore {
  constructor(instance) {
    this.exports = instance.exports;
    this.memory = this.exports.memory;
  }
  alloc(len) {
    const ptr = this.exports.alloc(len);
    if (ptr === 0) throw new Error(`alloc(${len}) failed`);
    return ptr;
  }
  dealloc(ptr, len) {
    this.exports.dealloc(ptr, len);
  }
  writeF32(arr) {
    const ptr = this.alloc(arr.length * 4);
    new Float32Array(this.memory.buffer, ptr, arr.length).set(arr);
    return { ptr, len: arr.length * 4 };
  }
  free(...bufs) {
    for (const b of bufs) this.dealloc(b.ptr, b.len);
  }
  memBytes() {
    return this.memory.buffer.byteLength;
  }
}

async function loadZig() {
  const bytes = readFileSync(ZIG_WASM);
  const { instance } = await WebAssembly.instantiate(bytes, {});
  return new ZigCore(instance);
}

// --- pipeline params (mirrors wasm_benchmark.mjs / evoc defaults) ---
const SEED = 0n;
const N_NEIGHBORS = 15;
const MIN_SAMPLES = 5;
const N_EPOCHS = 50;
const BASE_MIN_CLUSTER_SIZE = 5n;

function rustFitPredict(core, data, n, d) {
  const buf = core.writeF32(data);
  const outLabels = core.alloc(n * 4);
  const outStrengths = core.alloc(n * 4);
  const status = core.exports.wasm_evoc_fit_predict(
    buf.ptr, n, d, SEED,
    0.5, BASE_MIN_CLUSTER_SIZE, N_NEIGHBORS, MIN_SAMPLES, N_EPOCHS, 1.0, 0.2, 10, 20, 0,
    outLabels, outStrengths,
  );
  if (status < 1) throw new Error(`wasm_evoc_fit_predict status ${status}`);
  core.free(buf, { ptr: outLabels, len: n * 4 }, { ptr: outStrengths, len: n * 4 });
}

function zigFitPredict(core, data, n, d) {
  const buf = core.writeF32(data);
  const outLabels = core.alloc(n * 8);
  const status = core.exports.evoc_fit_predict(
    buf.ptr, n, d, SEED,
    0.5, BASE_MIN_CLUSTER_SIZE, N_NEIGHBORS, MIN_SAMPLES, N_EPOCHS, 1.0, 0.2, 10, 20, 0,
    outLabels,
  );
  if (status !== 0) throw new Error(`evoc_fit_predict status ${status}`);
  core.free(buf, { ptr: outLabels, len: n * 8 });
}

// matches clustering.rs's derivation (leaf_size = max(10, n_neighbors),
// n_iters = max(5, log2(n)), effective_max_candidates = min(60, 1.5*k))
function knnLeafSize() {
  return Math.max(10, N_NEIGHBORS);
}
function knnNIters(n) {
  return Math.max(5, Math.round(Math.log2(n)));
}
function knnMaxCandidates() {
  return Math.min(60, Math.floor(N_NEIGHBORS * 1.5));
}

function rustKnn(core, data, n, d) {
  const buf = core.writeF32(data);
  const outIdx = core.alloc(n * N_NEIGHBORS * 4);
  const outDist = core.alloc(n * N_NEIGHBORS * 4);
  const status = core.exports.wasm_knn_graph(
    buf.ptr, n, d, N_NEIGHBORS, knnLeafSize(), knnNIters(n), knnMaxCandidates(), 0.001, SEED, outIdx, outDist,
  );
  if (status !== 0) throw new Error(`wasm_knn_graph status ${status}`);
  const idx = new Int32Array(core.memory.buffer.slice(outIdx, outIdx + n * N_NEIGHBORS * 4));
  core.free(buf, { ptr: outIdx, len: n * N_NEIGHBORS * 4 }, { ptr: outDist, len: n * N_NEIGHBORS * 4 });
  return idx;
}

function zigKnn(core, data, n, d) {
  const buf = core.writeF32(data);
  const outIdx = core.alloc(n * N_NEIGHBORS * 4);
  const outDist = core.alloc(n * N_NEIGHBORS * 4);
  const status = core.exports.knn_graph(
    buf.ptr, n, d, N_NEIGHBORS, BigInt(knnLeafSize()), knnNIters(n), knnMaxCandidates(), 0.001, 200n, 1, SEED, outIdx, outDist,
  );
  if (status !== 0) throw new Error(`knn_graph status ${status}`);
  const idx = new Int32Array(core.memory.buffer.slice(outIdx, outIdx + n * N_NEIGHBORS * 4));
  core.free(buf, { ptr: outIdx, len: n * N_NEIGHBORS * 4 }, { ptr: outDist, len: n * N_NEIGHBORS * 4 });
  return idx;
}

function rustBoruvka(core, data, n, d) {
  const buf = core.writeF32(data);
  const nEdges = n - 1;
  const outPtr = core.alloc(nEdges * 3 * 4);
  const status = core.exports.wasm_boruvka_mst(buf.ptr, n, d, MIN_SAMPLES, outPtr);
  if (status !== nEdges) throw new Error(`wasm_boruvka_mst status ${status}`);
  const flat = new Float32Array(core.memory.buffer.slice(outPtr, outPtr + nEdges * 3 * 4));
  core.free(buf, { ptr: outPtr, len: nEdges * 3 * 4 });
  return flat;
}

function zigBoruvka(core, data, n, d) {
  const buf = core.writeF32(data);
  const nEdges = Number(core.exports.boruvka_mst_edge_count(n));
  const leftPtr = core.alloc(nEdges * 4);
  const rightPtr = core.alloc(nEdges * 4);
  const distPtr = core.alloc(nEdges * 4);
  const status = core.exports.boruvka_mst(buf.ptr, n, d, MIN_SAMPLES, 40n, 1, leftPtr, rightPtr, distPtr);
  if (status !== 0) throw new Error(`boruvka_mst status ${status}`);
  const left = new Float32Array(core.memory.buffer.slice(leftPtr, leftPtr + nEdges * 4));
  const right = new Float32Array(core.memory.buffer.slice(rightPtr, rightPtr + nEdges * 4));
  const dist = new Float32Array(core.memory.buffer.slice(distPtr, distPtr + nEdges * 4));
  core.free(buf, { ptr: leftPtr, len: nEdges * 4 }, { ptr: rightPtr, len: nEdges * 4 }, { ptr: distPtr, len: nEdges * 4 });
  return { left, right, dist };
}

function rustClusterTreeLabels(core, edgesFlat, n) {
  const nEdges = n - 1;
  const ptr = core.alloc(edgesFlat.length * 4);
  new Float32Array(core.memory.buffer, ptr, edgesFlat.length).set(edgesFlat);
  const outLabels = core.alloc(n * 4);
  const outStrengths = core.alloc(n * 4);
  const status = core.exports.wasm_cluster_tree_labels(ptr, nEdges, n, 5n, outLabels, outStrengths);
  if (status !== 0) throw new Error(`wasm_cluster_tree_labels status ${status}`);
  core.free({ ptr, len: edgesFlat.length * 4 }, { ptr: outLabels, len: n * 4 }, { ptr: outStrengths, len: n * 4 });
}

function zigClusterTreeLabels(core, edges, n) {
  const nEdges = edges.left.length;
  const flat = new Float32Array(nEdges * 3);
  for (let i = 0; i < nEdges; i++) {
    flat[i * 3] = edges.left[i];
    flat[i * 3 + 1] = edges.right[i];
    flat[i * 3 + 2] = edges.dist[i];
  }
  const ptr = core.alloc(flat.length * 4);
  new Float32Array(core.memory.buffer, ptr, flat.length).set(flat);
  const outLabels = core.alloc(n * 4);
  const outStrengths = core.alloc(n * 4);
  const status = core.exports.cluster_tree_labels(ptr, nEdges, n, 5n, outLabels, outStrengths);
  if (status !== 0) throw new Error(`cluster_tree_labels status ${status}`);
  core.free({ ptr, len: flat.length * 4 }, { ptr: outLabels, len: n * 4 }, { ptr: outStrengths, len: n * 4 });
}

// build a trivial symmetric CSR graph from knn indices (weight=1.0) purely
// to drive node_embedding's SGD stage in isolation -- NOT a claim this is
// the reference's actual graph_construction output, just enough structure
// (n_neighbors edges/vertex) to time the embedding stage at this n.
function csrFromKnn(idx, n, k) {
  const nnz = n * k;
  const indptr = new Uint32Array(n + 1);
  for (let i = 0; i <= n; i++) indptr[i] = i * k;
  const indices = new Uint32Array(nnz);
  const data = new Float32Array(nnz);
  for (let i = 0; i < nnz; i++) {
    indices[i] = Math.max(0, idx[i]);
    data[i] = 1.0;
  }
  return { indptr, indices, data, nnz };
}

function rustNodeEmbedding(core, graph, n) {
  const indptrPtr = core.alloc(graph.indptr.length * 4);
  new Uint32Array(core.memory.buffer, indptrPtr, graph.indptr.length).set(graph.indptr);
  const indicesPtr = core.alloc(graph.indices.length * 4);
  new Uint32Array(core.memory.buffer, indicesPtr, graph.indices.length).set(graph.indices);
  const dataPtr = core.alloc(graph.data.length * 4);
  new Float32Array(core.memory.buffer, dataPtr, graph.data.length).set(graph.data);
  const nComponents = 8;
  const outPtr = core.alloc(n * nComponents * 4);
  const status = core.exports.wasm_node_embedding(
    indptrPtr, indicesPtr, dataPtr, n, graph.nnz, nComponents, N_EPOCHS,
    0, 1.0, 5.0, 0.0, SEED, outPtr,
  );
  if (status !== 0) throw new Error(`wasm_node_embedding status ${status}`);
  core.free(
    { ptr: indptrPtr, len: graph.indptr.length * 4 },
    { ptr: indicesPtr, len: graph.indices.length * 4 },
    { ptr: dataPtr, len: graph.data.length * 4 },
    { ptr: outPtr, len: n * nComponents * 4 },
  );
}

function zigNodeEmbedding(core, graph, n) {
  const indptrPtr = core.alloc(graph.indptr.length * 4);
  new Uint32Array(core.memory.buffer, indptrPtr, graph.indptr.length).set(graph.indptr);
  const indicesPtr = core.alloc(graph.indices.length * 4);
  new Uint32Array(core.memory.buffer, indicesPtr, graph.indices.length).set(graph.indices);
  const dataPtr = core.alloc(graph.data.length * 4);
  new Float32Array(core.memory.buffer, dataPtr, graph.data.length).set(graph.data);
  const nComponents = 8;
  const outPtr = core.alloc(n * nComponents * 4);
  const status = core.exports.node_embedding(
    indptrPtr, indicesPtr, dataPtr, n, graph.nnz, nComponents, N_EPOCHS,
    0, 1.0, 5.0, 0.0, SEED, outPtr,
  );
  if (status !== 0) throw new Error(`node_embedding status ${status}`);
  core.free(
    { ptr: indptrPtr, len: graph.indptr.length * 4 },
    { ptr: indicesPtr, len: graph.indices.length * 4 },
    { ptr: dataPtr, len: graph.data.length * 4 },
    { ptr: outPtr, len: n * nComponents * 4 },
  );
}

async function main() {
  const sizesArg = process.argv[2];
  const sizes = sizesArg ? sizesArg.split(",").map(Number) : [2000, 10000, 30000];

  const rust = await loadRust();
  const zig = await loadZig();

  for (const n of sizes) {
    console.log(`\n=== n=${n}, d=${N_FEATURES} ===`);
    const data = loadData(n);

    // Fresh instances for the end-to-end memory reading: wasm linear memory
    // only grows, never shrinks (no munmap equivalent), so measuring
    // memory.buffer.byteLength on an instance that has already run other
    // stages in this same process reports CUMULATIVE growth across all
    // prior calls, not this call's peak. A fresh instance isolates the
    // single fit_predict call's own footprint (still includes allocator
    // overhead/fragmentation from that one call, which is real and part of
    // what a browser tab would see for a single fit_predict-only page).
    console.log("  -- end to end (fresh wasm instance per call, for isolated memory reading) --");
    try {
      const freshRust = await loadRust();
      await time("rust wasm_evoc_fit_predict", () => rustFitPredict(freshRust, data, n, N_FEATURES));
      console.log(`    rust memory: ${fmtBytes(freshRust.memBytes())}`);
    } catch (e) {
      console.log(`    rust FAILED: ${e.message}`);
    }
    try {
      const freshZig = await loadZig();
      await time("zig  evoc_fit_predict", () => zigFitPredict(freshZig, data, n, N_FEATURES));
      console.log(`    zig  memory: ${fmtBytes(freshZig.memBytes())}`);
    } catch (e) {
      console.log(`    zig  FAILED: ${e.message}`);
    }

    console.log("  -- stage: knn_graph --");
    let rustIdx, zigIdx;
    try {
      rustIdx = await time("rust wasm_knn_graph", () => rustKnn(rust, data, n, N_FEATURES));
    } catch (e) {
      console.log(`    rust FAILED: ${e.message}`);
    }
    try {
      zigIdx = await time("zig  knn_graph", () => zigKnn(zig, data, n, N_FEATURES));
    } catch (e) {
      console.log(`    zig  FAILED: ${e.message}`);
    }

    console.log("  -- stage: boruvka_mst --");
    let rustEdges, zigEdges;
    try {
      rustEdges = await time("rust wasm_boruvka_mst", () => rustBoruvka(rust, data, n, N_FEATURES));
    } catch (e) {
      console.log(`    rust FAILED: ${e.message}`);
    }
    try {
      zigEdges = await time("zig  boruvka_mst", () => zigBoruvka(zig, data, n, N_FEATURES));
    } catch (e) {
      console.log(`    zig  FAILED: ${e.message}`);
    }

    console.log("  -- stage: cluster_tree_labels --");
    if (rustEdges) {
      try {
        await time("rust wasm_cluster_tree_labels", () => rustClusterTreeLabels(rust, rustEdges, n));
      } catch (e) {
        console.log(`    rust FAILED: ${e.message}`);
      }
    }
    if (zigEdges) {
      try {
        await time("zig  cluster_tree_labels", () => zigClusterTreeLabels(zig, zigEdges, n));
      } catch (e) {
        console.log(`    zig  FAILED: ${e.message}`);
      }
    }

    console.log("  -- stage: node_embedding (n_components=8, n_epochs=50, synthetic knn-derived graph) --");
    if (rustIdx) {
      try {
        const graph = csrFromKnn(rustIdx, n, N_NEIGHBORS);
        await time("rust wasm_node_embedding", () => rustNodeEmbedding(rust, graph, n));
      } catch (e) {
        console.log(`    rust FAILED: ${e.message}`);
      }
    }
    if (zigIdx) {
      try {
        const graph = csrFromKnn(zigIdx, n, N_NEIGHBORS);
        await time("zig  node_embedding", () => zigNodeEmbedding(zig, graph, n));
      } catch (e) {
        console.log(`    zig  FAILED: ${e.message}`);
      }
    }
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
